import {SignatureJwk} from "../crypto/signature/jwk/JwkSignatureAlgorithm";

/**
 * A KMS wallet: one private signature key (generated by a plugin), one actor seed and one
 * wallet API key. Neither the private key, the actor seed nor the API key (except once, at
 * creation or regeneration) is ever returned by the KMS: only the public half is exposed.
 */
export interface KmsWallet {
    id: string;
    label?: string;
    pluginId: string;
    publicJwk: SignatureJwk;
    /** Admin key of the wallet (Carmentis string encoding, `sig:<alg>:pk:<hex>`). */
    adminPublicKey: string;
    /** X.509 chain (PEM, leaf first) attached to the wallet key, if any. */
    certificates: string[] | null;
    createdBy: string;
    createdAt: string;
}

/** A freshly created wallet. Its {@link apiKey} is returned only once: store it. */
export interface KmsCreatedWallet extends KmsWallet {
    /** Wallet API key (`wlt_…`). */
    apiKey: string;
}

/** Result of a wallet API key regeneration. The new key is returned only once. */
export interface KmsWalletApiKey {
    id: string;
    /** Wallet API key (`wlt_…`). */
    apiKey: string;
}

export interface KmsCreateWalletParams {
    /** Plugin generating the private key (default `local` on the server side). */
    pluginId?: string;
    /** Validated against the plugin's `key/create` JSON Schema, e.g. `{algorithm: "ES256"}`. */
    params?: Record<string, unknown>;
    label?: string;
}

/**
 * Methods a plugin or wallet may support. The server may report others, hence the open string type
 * on {@link KmsCapability.method}.
 */
export type KmsKnownMethod =
    | "key/create" | "key/public" | "sign/raw" | "sign/json"
    | "cert/get" | "cert/create-self-signed" | "cert/csr";

/** A method supported by a plugin or a wallet. */
export interface KmsCapability {
    method: KmsKnownMethod | (string & {});
    description?: string;
    /** JSON Schema (draft 2020-12) of the method parameters; absent when the method takes none. */
    params?: Record<string, unknown>;
}

/** An installed plugin, as returned by `GET /api/plugins`. */
export interface KmsPlugin {
    id: string;
    name: string;
    description?: string;
    version?: string;
    /** True for the plugin built into the server. */
    builtin: boolean;
    /** URL of the plugin icon. */
    icon?: string;
    capabilities: KmsCapability[];
}

export type KmsSignatureType = "json-canonical+utf8" | "jws";

export interface KmsSignJsonParams {
    /** Any JSON value (an object for the "jws" signature type). */
    payload: unknown;
    /** `purpose` is required, `signedAt` (ms) defaults to now. */
    context: { purpose: string; signedAt?: number; [key: string]: unknown };
    signatureType?: KmsSignatureType;
}

export type KmsSignJsonResult =
    | {
        signatureType: "json-canonical+utf8";
        context: { purpose: string; signedAt: number; [key: string]: unknown };
        /** Base64 signature. */
        signature: string;
        payload: unknown;
        publicKey: string;
    }
    | { signatureType: "jws"; jws: string; publicKey: string };

export type KmsPublicKeyFormat = "jwk" | "carmentis";

export interface KmsCertificateParams {
    subject?: string;
    san?: string[];
    validityDays?: number;
    [key: string]: unknown;
}

/** The object signed by the admin key in a signed request. */
export interface KmsSignedRequestPayload {
    /** Single-use nonce from `POST /api/wallets/challenge`. */
    challenge: string;
    /** HTTP method of the request carrying this payload. */
    method: string;
    /** API path of the request carrying this payload, without query string. */
    path: string;
    /** The operation input. */
    body: unknown;
}

/** Body of a signed request. */
export interface KmsSignedRequest {
    /** Admin public key, Carmentis string encoding. */
    publicKey: string;
    /** Base64 signature over the RFC 8785 canonical JSON of `payload`. */
    signature: string;
    payload: KmsSignedRequestPayload;
}

/** Credential of the wallet management endpoints (`/api/manage/wallets`). */
export type KmsManagementCredential =
    /** Global API key (`jwks_…`), sent as `x-api-key`. */
    | { apiKey: string }
    /** Administrator JWT (or global API key), sent as bearer token. */
    | { bearerToken: string };

/** Identifies the wallet a KMS-backed key belongs to. */
export interface KmsWalletReference {
    walletId: string;
}
